package oidcadapter
import("context";"crypto/rand";"crypto/rsa";"encoding/json";"net/http";"net/http/httptest";"net/url";"testing";"time";"github.com/go-jose/go-jose/v4";"github.com/go-jose/go-jose/v4/jwt")
func TestSignedOIDCExchangeValidation(t *testing.T){key,_:=rsa.GenerateKey(rand.Reader,2048);var base,token string;var verifier string
 server:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){switch r.URL.Path{case "/.well-known/openid-configuration":json.NewEncoder(w).Encode(map[string]any{"issuer":base,"authorization_endpoint":base+"/authorize","token_endpoint":base+"/token","jwks_uri":base+"/keys","id_token_signing_alg_values_supported":[]string{"RS256"}});case "/keys":json.NewEncoder(w).Encode(jose.JSONWebKeySet{Keys:[]jose.JSONWebKey{{Key:&key.PublicKey,KeyID:"key",Algorithm:"RS256",Use:"sig"}}});case "/token":r.ParseForm();verifier=r.Form.Get("code_verifier");w.Header().Set("Content-Type","application/json");json.NewEncoder(w).Encode(map[string]any{"access_token":"test","token_type":"Bearer","id_token":token})}}));defer server.Close();base=server.URL
 p,e:=New(context.Background(),base,"client","secret","https://app.test/auth/callback");if e!=nil{t.Fatal(e)};u,_:=url.Parse(p.AuthorizationURL("state","nonce","abcdefghijklmnopqrstuvwxyz012345678901234567890"));q:=u.Query();if q.Get("code_challenge_method")!="S256"||q.Get("state")!="state"||q.Get("nonce")!="nonce"||q.Get("redirect_uri")!="https://app.test/auth/callback"{t.Fatal(q)}
 sign:=func(iss,aud,nonce string,k *rsa.PrivateKey,expiry time.Time)string{s,_:=jose.NewSigner(jose.SigningKey{Algorithm:jose.RS256,Key:k},(&jose.SignerOptions{}).WithHeader("kid","key"));v,e:=jwt.Signed(s).Claims(map[string]any{"iss":iss,"sub":"exact-subject","aud":aud,"exp":expiry.Unix(),"iat":time.Now().Unix(),"nonce":nonce}).Serialize();if e!=nil{t.Fatal(e)};return v}
 token=sign(base,"client","nonce",key,time.Now().Add(time.Minute));i,e:=p.Exchange(context.Background(),"code","pkce-verifier","nonce");if e!=nil||i.Subject!="exact-subject"||verifier!="pkce-verifier"{t.Fatal(i,e,verifier)}
 wrong,_:=rsa.GenerateKey(rand.Reader,2048)
 for _,tc:=range []struct{name,iss,aud,nonce string;key *rsa.PrivateKey;expiry time.Time}{{"issuer","https://evil.test","client","nonce",key,time.Now().Add(time.Minute)},{"audience",base,"other","nonce",key,time.Now().Add(time.Minute)},{"nonce",base,"client","other",key,time.Now().Add(time.Minute)},{"signature",base,"client","nonce",wrong,time.Now().Add(time.Minute)},{"expired",base,"client","nonce",key,time.Now().Add(-time.Hour)}}{t.Run(tc.name,func(t *testing.T){token=sign(tc.iss,tc.aud,tc.nonce,tc.key,tc.expiry);if _,e=p.Exchange(context.Background(),"code","verifier","nonce");e==nil{t.Fatal("accepted invalid ID token")}})}
}
